package io.github.resonancefx.model

import org.json.JSONArray
import org.json.JSONObject

/**
 * The engine's own measurements of every effect (assets/measurements.json, generated by
 * tests/measure-engine.sh for each release): what each effect actually does, not what it claims.
 */
data class Measurements(
    val engine: String,
    val method: String,
    val freqs: List<Float>,
    val effects: List<Effect>,
) {
    data class Effect(
        val section: String,
        val name: String,
        val settings: String,
        /** Gain (dB) of a -24 dBFS sine at each of [Measurements.freqs]. */
        val response: List<Float?>,
        /** Gain into the other channel when only one is driven (crossfeed, spatial). */
        val crosstalk: List<Float?>?,
        val noiseDb: Float?,
        val thd100: Float?,
        val thd1k: Float?,
        val gainLoud: Float?,
        val gainQuiet: Float?,
        val widthDb: Float?,
        val tailDb: Float?,
    )

    companion object {
        fun parse(text: String): Measurements {
            val o = JSONObject(text)
            fun JSONObject.num(key: String): Float? = if (has(key) && !isNull(key)) getDouble(key).toFloat() else null
            fun list(a: JSONArray?): List<Float?>? = a?.let { arr ->
                (0 until arr.length()).map { if (arr.isNull(it)) null else arr.getDouble(it).toFloat() }
            }
            val effects = o.getJSONArray("effects")
            return Measurements(
                engine = o.getString("engine"),
                method = o.optString("method"),
                freqs = list(o.getJSONArray("freqs"))!!.map { it ?: 0f },
                effects = (0 until effects.length()).map { i ->
                    val e = effects.getJSONObject(i)
                    Effect(
                        section = e.getString("section"),
                        name = e.getString("name"),
                        settings = e.optString("settings"),
                        response = list(e.getJSONArray("response"))!!,
                        crosstalk = list(e.optJSONArray("crosstalk")),
                        noiseDb = e.num("noiseDb"),
                        thd100 = e.num("thd100"),
                        thd1k = e.num("thd1k"),
                        gainLoud = e.num("gain1kLoud"),
                        gainQuiet = e.num("gain1kQuiet"),
                        widthDb = e.num("widthDb"),
                        tailDb = e.num("tailDb"),
                    )
                },
            )
        }
    }
}
